"""The staged env files are sourced by bash, so only an allowlist of forms is read.

The engine guards against mistakes and generated-file drift in files the flash
tools trust anyway; it never executes them.
"""

import pytest

from avocado_tegraflash import EngineError
from avocado_tegraflash.plainenv import read_plain_env

ENV_NAME = ".env.initrd-flash"
PRESIGN_NAME = ".presigning-vars"

# The tegraflash-bsp recipe's heredoc, expanded for a qemu-free Orin Nano build.
GENERATED = """# Environment settings for initrd-flash
# Generated by tegraflash-bsp recipe
MACHINE="avocado-jetson-orin-nano"
DTBFILE="tegra234-p3768-0000+p3767-0005-nv.dtb"
ROOTFS_IMAGE="avocado-image-rootfs-avocado-jetson-orin-nano.erofs-lz4"
LNXFILE="boot.img"
EMC_BCT="tegra234-mb1-bct-memcfg-p3767-0000.dtsi"
ODMDATA="gbe-uphy-config-8,hsstp-lane-map-3,hsio-uphy-lane-map-0000000"
CHIPID="0x23"
FLASH_HELPER="tegra234-flash-helper"
TOSIMGFILENAME="tos-optee_t234.img"
BOOTDEV="mmcblk0p1"
ROOTFS_DEVICE="nvme0n1"
EXTERNAL_ROOTFS_DRIVE=1
NO_INTERNAL_STORAGE=1
DATAFILE="avocado-image-var-avocado-jetson-orin-nano.btrfs"
"""


def read(tmp_path, text, presign=None):
    path = tmp_path / ENV_NAME
    path.write_text(text)
    if presign is not None:
        (tmp_path / PRESIGN_NAME).write_text(presign)
    return read_plain_env(path)


def refused(tmp_path, text, presign=None):
    with pytest.raises(EngineError) as exc:
        read(tmp_path, text, presign)
    return str(exc.value)


def test_a_real_generated_file_is_accepted_and_every_checked_key_is_read(tmp_path):
    assert read(tmp_path, GENERATED) == {
        "ROOTFS_IMAGE": "avocado-image-rootfs-avocado-jetson-orin-nano.erofs-lz4",
        "ROOTFS_DEVICE": "nvme0n1",
        "DATAFILE": "avocado-image-var-avocado-jetson-orin-nano.btrfs",
        "EXTERNAL_ROOTFS_DRIVE": "1",
        "NO_INTERNAL_STORAGE": "1",
        "TOSIMGFILENAME": "tos-optee_t234.img",
    }


def test_plain_assignments_are_read_with_quotes_removed(tmp_path):
    env = read(tmp_path, 'ROOTFS_IMAGE="r.img"\nROOTFS_DEVICE=nvme0n1\nDATAFILE=\'v.img\'\nOTHER=1\n')
    assert env == {"ROOTFS_IMAGE": "r.img", "ROOTFS_DEVICE": "nvme0n1", "DATAFILE": "v.img"}


def test_the_last_plain_assignment_wins(tmp_path):
    assert read(tmp_path, "ROOTFS_IMAGE=a.img\nROOTFS_IMAGE=b.img\n") == {"ROOTFS_IMAGE": "b.img"}


def test_absent_keys_are_absent_from_the_result(tmp_path):
    assert read(tmp_path, "BOOTDEV=x\n") == {}


def test_a_similarly_named_variable_is_not_the_key(tmp_path):
    assert read(tmp_path, "MY_ROOTFS_IMAGE=a\nROOTFS_IMAGE_X=b\nDATAFILE_B=c\n") == {}


def test_a_comment_mentioning_a_key_is_not_an_assignment(tmp_path):
    assert read(tmp_path, "# ROOTFS_IMAGE=a.img\n  # export ROOTFS_DEVICE=x\n") == {}


def test_a_read_of_a_key_is_allowed_in_both_spellings(tmp_path):
    text = 'ROOTFS_IMAGE=a.img\nX=$ROOTFS_IMAGE\nY="${ROOTFS_IMAGE}"\n'
    assert read(tmp_path, text) == {"ROOTFS_IMAGE": "a.img"}


@pytest.mark.parametrize(
    "line",
    [
        ' ROOTFS_IMAGE="big.img"',
        "\tROOTFS_IMAGE=big.img",
        'export ROOTFS_IMAGE="big.img"',
        "declare -x ROOTFS_IMAGE=big.img",
        "local ROOTFS_IMAGE=big.img",
        "readonly ROOTFS_IMAGE=big.img",
        "ROOTFS_IMAGE+=big.img",
        "ROOTFS_IMAGE =big.img",
        "X=1; ROOTFS_IMAGE=big.img",
        "true && ROOTFS_IMAGE=big.img",
        "false || ROOTFS_IMAGE=big.img",
        "X=1 ; ROOTFS_IMAGE=big.img",
        "true;ROOTFS_IMAGE=big.img",
        "true&&ROOTFS_IMAGE=big.img",
        "false||ROOTFS_IMAGE=big.img",
        "ROOTFS_IMAGE=a.img; ROOTFS_IMAGE=big.img",
        "(ROOTFS_IMAGE=big.img)",
        'eval "ROOTFS_IMAGE=big.img"',
        "printf -v ROOTFS_IMAGE big.img",
        "read -r ROOTFS_IMAGE <<< big.img",
        "unset ROOTFS_IMAGE",
        ": ${ROOTFS_IMAGE:=big.img}",
        "ROOTFS_IMAGE[0]=big.img",
    ],
)
def test_a_non_plain_use_of_a_key_is_refused_naming_file_line_and_key(tmp_path, line):
    path = tmp_path / ENV_NAME
    path.write_text(f"BOOTDEV=x\n{line}\n")
    with pytest.raises(EngineError) as exc:
        read_plain_env(path)
    msg = str(exc.value)
    assert str(path) in msg and ":2" in msg and "ROOTFS_IMAGE" in msg
    assert "sources" in msg and "bash" in msg and "column-0" in msg


@pytest.mark.parametrize(
    "line",
    [
        'eval "ROOTFS_DEVICE=sda"',
        "eval 'ROOTFS_DEVICE=sda'",
        "eval $'ROOTFS_DEVICE=sda'",
        "printf -v ROOTFS_DEVICE sda",
        "read -r ROOTFS_DEVICE <<< sda",
        "mapfile ROOTFS_DEVICE",
        "ROOTFS_DEVICE[0]=sda",
        "declare -n R=ROOTFS_DEVICE",
        "unset ROOTFS_DEVICE",
        ": ${ROOTFS_DEVICE:=sda}",
        "export ROOTFS_DEVICE=sda",
        "  ROOTFS_DEVICE=sda",
        "ROOTFS_DEVICE+=sda",
        "ROOTFS_DEVICE =sda",
    ],
)
def test_every_reviewer_spelling_of_a_device_override_is_refused(tmp_path, line):
    assert "ROOTFS_DEVICE" in refused(tmp_path, f'ROOTFS_DEVICE="nvme0n1"\n{line}\n')


@pytest.mark.parametrize("line", [". ./other", "source ./other", "eval foo", "  . ./other", "\tsource x"])
def test_a_line_that_runs_another_file_or_evals_is_refused(tmp_path, line):
    msg = refused(tmp_path, f"A=1\n{line}\n")
    assert ":2" in msg and "bash" in msg


@pytest.mark.parametrize("key", ["ROOTFS_DEVICE", "ROOTFS_IMAGE", "DATAFILE", "EXTERNAL_ROOTFS_DRIVE", "NO_INTERNAL_STORAGE", "TOSIMGFILENAME"])
def test_every_checked_key_is_scanned(tmp_path, key):
    with pytest.raises(EngineError, match=key):
        read(tmp_path, f"export {key}=x\n")


def test_a_non_plain_line_after_a_plain_one_is_still_refused(tmp_path):
    with pytest.raises(EngineError, match=r":2"):
        read(tmp_path, "ROOTFS_IMAGE=a.img\nexport ROOTFS_IMAGE=b.img\n")


def test_line_numbers_count_newlines_only(tmp_path):
    with pytest.raises(EngineError, match=r":3"):
        read(tmp_path, "A=1\x0cB=2\nC=3\n  ROOTFS_IMAGE=x\n")


def test_a_nul_byte_is_refused(tmp_path):
    msg = refused(tmp_path, "BOOTDEV=x\nROOTFS_DEV\x00ICE=sda\n")
    assert "NUL" in msg


def test_a_line_ending_in_a_backslash_is_refused(tmp_path):
    msg = refused(tmp_path, "ROOTFS_\\\nDEVICE=sda\n")
    assert ":1" in msg and "backslash" in msg


# the presigning file is sourced after the env file, so it can override it


def test_a_presigning_vars_assignment_overrides_the_env_file(tmp_path):
    env = read(tmp_path, "ROOTFS_DEVICE=nvme0n1\n", presign="ROOTFS_DEVICE=sda\n")
    assert env == {"ROOTFS_DEVICE": "sda"}


def test_a_presigning_vars_file_is_read_even_without_the_key_in_the_env_file(tmp_path):
    assert read(tmp_path, "BOOTDEV=x\n", presign="ROOTFS_IMAGE=signed.img\n") == {"ROOTFS_IMAGE": "signed.img"}


@pytest.mark.parametrize(
    "line",
    [
        "export ROOTFS_DEVICE=sda",
        'eval "ROOTFS_DEVICE=sda"',
        "printf -v ROOTFS_DEVICE sda",
        "ROOTFS_DEVICE[0]=sda",
        "true;ROOTFS_DEVICE=sda",
        ". ./other",
    ],
)
def test_a_non_plain_form_in_presigning_vars_is_refused_naming_that_file(tmp_path, line):
    msg = refused(tmp_path, "ROOTFS_DEVICE=nvme0n1\n", presign=f"A=1\n{line}\n")
    assert str(tmp_path / PRESIGN_NAME) in msg and ":2" in msg


def test_a_nul_byte_in_presigning_vars_is_refused(tmp_path):
    assert "NUL" in refused(tmp_path, "A=1\n", presign="A=1\x00\n")


# value rules


@pytest.mark.parametrize(
    "key,value",
    [
        ("DATAFILE", ""),
        ("DATAFILE", '""'),
        ("DATAFILE", "'\"var.btrfs\"'"),
        ("DATAFILE", '"var.btrfs'),
        ("DATAFILE", "var.btrfs'"),
        ("DATAFILE", "\"var.btrfs'"),
        ("DATAFILE", "$HOME"),
        ("DATAFILE", "a$(id)"),
        ("DATAFILE", "`id`"),
        ("DATAFILE", "a;b"),
        ("DATAFILE", "a&b"),
        ("DATAFILE", "a|b"),
        ("DATAFILE", "a(b)"),
        ("DATAFILE", "a b"),
        ("DATAFILE", "a\\b"),
        ("DATAFILE", "../x"),
        ("DATAFILE", ".."),
        ("DATAFILE", "."),
        ("DATAFILE", "dir/x"),
        ("ROOTFS_IMAGE", ""),
        ("ROOTFS_IMAGE", "a b.img"),
        ("TOSIMGFILENAME", ""),
        ("TOSIMGFILENAME", "../../escaped.img"),
        ("TOSIMGFILENAME", "/abs/tos.img"),
        ("TOSIMGFILENAME", "sub/tos.img"),
        ("ROOTFS_DEVICE", ""),
        ("ROOTFS_DEVICE", "/dev/sda"),
        ("ROOTFS_DEVICE", "sda p1"),
        ("ROOTFS_DEVICE", "sda+1"),
        ("EXTERNAL_ROOTFS_DRIVE", "2"),
        ("EXTERNAL_ROOTFS_DRIVE", ""),
        ("EXTERNAL_ROOTFS_DRIVE", "01"),
        ("EXTERNAL_ROOTFS_DRIVE", "yes"),
        ("NO_INTERNAL_STORAGE", "-1"),
        ("NO_INTERNAL_STORAGE", "1 0"),
    ],
)
def test_a_value_outside_the_allowed_shape_is_refused_naming_key_and_line(tmp_path, key, value):
    msg = refused(tmp_path, f"A=1\n{key}={value}\n")
    assert key in msg and ":2" in msg


def test_trailing_blanks_after_a_value_are_not_part_of_it(tmp_path):
    assert read(tmp_path, "NO_INTERNAL_STORAGE=1 \t\n") == {"NO_INTERNAL_STORAGE": "1"}


@pytest.mark.parametrize(
    "key,value",
    [
        ("ROOTFS_IMAGE", "avocado-image-rootfs-x.erofs-lz4"),
        ("DATAFILE", "var+x_1.btrfs"),
        ("TOSIMGFILENAME", "tos-optee_t264.img"),
        ("ROOTFS_DEVICE", "mmcblk0"),
        ("EXTERNAL_ROOTFS_DRIVE", "0"),
        ("NO_INTERNAL_STORAGE", "1"),
    ],
)
@pytest.mark.parametrize("quote", ["", '"', "'"])
def test_an_allowed_value_is_read_bare_or_in_one_matching_pair_of_quotes(tmp_path, key, value, quote):
    assert read(tmp_path, f"{key}={quote}{value}{quote}\n") == {key: value}


# code that is run from a position other than the first word of the line


@pytest.mark.parametrize(
    "line",
    [
        "[ -e x ] && . ./x",
        "true; . ./x",
        "test -f x && source x",
        "builtin source x",
        "command . ./x",
        "if a; then . ./x; fi",
        "a || eval foo",
        "a | source x",
        "do . ./x",
        "{ . ./x; }",
        "( . ./x )",
        "! . ./x",
    ],
)
def test_code_run_from_a_later_command_position_is_refused(tmp_path, line):
    msg = refused(tmp_path, f"A=1\n{line}\n")
    assert ":2" in msg and "bash" in msg


@pytest.mark.parametrize("line", ["# . ./x", "  # source x", "A=1", 'B="a.b"', "echo source", "X=$ROOTFS_IMAGE"])
def test_ordinary_lines_and_comments_are_not_mistaken_for_sourcing(tmp_path, line):
    read(tmp_path, f"ROOTFS_IMAGE=a.img\n{line}\n")


def test_a_trailing_comment_on_a_checked_key_is_refused_and_named(tmp_path):
    msg = refused(tmp_path, "ROOTFS_IMAGE=foo # note\n")
    assert "trailing comment" in msg and "unmatched quote" not in msg and ":1" in msg


def test_a_trailing_comment_after_a_quoted_value_is_named_not_called_an_unmatched_quote(tmp_path):
    msg = refused(tmp_path, 'ROOTFS_IMAGE="foo" # note\n')
    assert "trailing comment" in msg and "unmatched quote" not in msg


def test_a_hash_inside_a_word_is_not_a_comment_but_fails_the_shape(tmp_path):
    msg = refused(tmp_path, "ROOTFS_IMAGE=a#b\n")
    assert "trailing comment" not in msg and "ROOTFS_IMAGE" in msg


def test_a_crlf_line_ending_is_named(tmp_path):
    msg = refused(tmp_path, 'ROOTFS_IMAGE="a.img"\r\n')
    assert "carriage return" in msg and "unmatched quote" not in msg and ":1" in msg


def test_a_leading_blank_in_a_value_is_refused(tmp_path):
    assert "ROOTFS_DEVICE" in refused(tmp_path, "ROOTFS_DEVICE= nvme0n1\n")


def test_a_comment_line_that_mentions_a_key_is_still_skipped(tmp_path):
    assert read(tmp_path, "# ROOTFS_IMAGE=x # note\nROOTFS_IMAGE=a.img\n") == {"ROOTFS_IMAGE": "a.img"}


# every value says which file and line it came from


def test_a_value_carries_the_file_and_line_that_set_it(tmp_path):
    env = read(tmp_path, "A=1\nROOTFS_DEVICE=nvme0n1\n", presign="B=2\n\nROOTFS_DEVICE=sda\nDATAFILE=v.img\n")
    assert (env["ROOTFS_DEVICE"].path, env["ROOTFS_DEVICE"].line) == (tmp_path / PRESIGN_NAME, 3)
    assert env["DATAFILE"].where == f"{tmp_path / PRESIGN_NAME}:4"


def test_a_value_set_only_in_the_env_file_cites_the_env_file(tmp_path):
    env = read(tmp_path, "A=1\nROOTFS_IMAGE=r.img\n", presign="B=2\n")
    assert env["ROOTFS_IMAGE"].where == f"{tmp_path / ENV_NAME}:2"
